const v49Sha=b=>createHash('sha256').update(b).digest('hex');
const v49Tuple=p=>({path:p.path,bytes:p.bytes,sha256:p.sha256});
function v49SaveHexBytes(hex){assert.ok(typeof hex==='string'&&hex.length>0&&hex.length<=512*1024&&hex.length%2===0&&/^[0-9a-f]+$/i.test(hex),'Bounded even hexadecimal SAV payload');return Buffer.from(hex,'hex');}
function v49AssertPairBytes(a,b,label){for(const k of['sav0','sav1'])assert.ok(v49SaveHexBytes(a?.[k]).equals(v49SaveHexBytes(b?.[k])),label+' SAV bytes must match; hex letter case is not byte identity');}
function v49Path(p){assert.ok(typeof p==='string'&&p.length>0&&!p.startsWith('/')&&!p.includes('\\')&&!p.split('/').some(x=>!x||x==='.'||x==='..')&&!/^[a-z]:/i.test(p),'Bounded relative archive path');return p;}
function v49Pin(p){v49Path(p.path);assert.ok(Number.isSafeInteger(p.bytes)&&p.bytes>=0&&/^[0-9a-f]{64}$/.test(p.sha256));return v49Tuple(p);}
function v49Get(files,p,cap=32*1024*1024){v49Path(p);const b=files.get(p);assert.ok(Buffer.isBuffer(b),'Required original archive bytes: '+p);assert.ok(b.length<=cap,'One bounded archive input');return b;}
function v49Json(files,p,cap){return JSON.parse(v49Get(files,p,cap).toString('utf8'));}
function v49VerifyBytes(files,p,tuple,cap){const b=v49Get(files,p,cap);assert.deepEqual([b.length,v49Sha(b)],[tuple.bytes,tuple.sha256],'Original byte pin '+p);return b;}
function v49Budget(t){return{dailyRatio:t.meta.dailyRatio,monthlyRatio:t.meta.monthlyRatio,boutMax:t.meta.boutMax};}
function v49Map(t){const s=t.state,z=s.snapshot;return !s.menu.active&&!s.qty.active&&!s.record.active&&!z.fight.active&&!z.spe.active&&!z.result.active&&!z.top.active&&!z.report.active&&s.march.pick===1&&s.march.battlePick===0&&[0,7].includes(s.march.phase)&&s.overworld==='map';}
