const V49_PREFIX='docs/validation/m5-wood-city4-preparation-20261024-v49';
export function verifyV49Publication(root=process.cwd(),options={}){
 const readPublic=options.readPublic??(p=>v45ReadBounded(root,p));
 const readCurrent=options.readCurrent??(p=>{try{return v45ReadBounded(root,p);}catch(e){if(e.code==='ENOENT')return null;throw e;}});
 const C=JSON.parse(readPublic(V49_PREFIX+'.json'));assert.ok(Object.hasOwn(C,'observations'),'Final canonical observations are mandatory');
 assert.equal(C.reader.path,V49_PREFIX+'-verify.mjs');assert.deepEqual(v45Pin(C.reader.path,readPublic(C.reader.path)),C.reader);
 assert.equal(C.readerDependency.path,'docs/validation/m5-quantity-ack-refresh-20261024-v45-verify.mjs');assert.deepEqual(v45Pin(C.readerDependency.path,readCurrent(C.readerDependency.path)),C.readerDependency);
 const index=JSON.parse(readPublic(C.archive.path)),decoded=decodeV45Archive({index,readPart:p=>readPublic(p)});
 const evidence=verifyV49Envelope({files:decoded.files,canonical:C,readCurrent,readPublic,verifyActual:verifyV49City4Actual});
 const pngs=[];for(const [p,b]of decoded.files)if(C.runs.some(r=>p.startsWith(r.runDir.endsWith('/')?r.runDir:r.runDir+'/'))&&p.endsWith('.png'))pngs.push({pin:v45Pin(p,b),decoded:decodeV45Png(b)});
 assert.deepEqual(pngs,C.pngs,'Every ordinary actual PNG has complete CRC/IDAT/filter decoding');
 const F=JSON.parse(decoded.files.get(C.full.path)),raw=decoded.files.get(F.stdout.path),zipped=readPublic(C.fullStdoutGzip.path);assert.deepEqual(v45Pin(C.fullStdoutGzip.path,zipped),C.fullStdoutGzip);assert.ok(gunzipSync(zipped,{maxOutputLength:raw.length}).equals(raw),'Public gzip equals the complete original full stdout');
 for(const p of C.planPins){assert.deepEqual(v45Pin(p.path,readCurrent(p.path)),p);assert.ok(decoded.files.has(p.path));assert.deepEqual(v45Pin(p.path,decoded.files.get(p.path)),p);}
 return{accepted:true,logicalFiles:decoded.logicalFiles,uniqueBlobs:decoded.physicalBlobs,ordinaryPngsDecoded:pngs.length,sourceBinding:evidence.sourceBinding,facts:evidence.facts,newBrowserRuns:0,newGameInputs:0,newTestExecutions:0,actualFlagsRewritten:false};
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url))console.log(JSON.stringify(verifyV49Publication()));
